window.FWDATA = {
"sets":{"lokaal":{"t":"Lokaal of via de gateway?","intro":"Een client heeft <b>192.168.20.115/24</b>, gateway 192.168.20.1. Stuurt hij het pakket rechtstreeks of naar de gateway?","cats":[{"t":"Lokaal","d":"rechtstreeks","c":"#14799B","l":"voor een bestemming in het eigen subnet (zelfde netwerkdeel na het masker)"},{"t":"Gateway","d":"via 192.168.20.1","c":"#EB6008","l":"voor een bestemming buiten het eigen subnet"}],"items":[{"q":"Bestemming <code>192.168.20.120</code>","a":"Lokaal","e":"Met /24 vergelijk je de eerste drie getallen: 192.168.20 = 192.168.20. Rechtstreeks, via ARP."},{"q":"Bestemming <code>192.168.10.10</code> (de Windows Server)","a":"Gateway","e":"192.168.10 ≠ 192.168.20: ander subnet, dus naar de gateway."},{"q":"Bestemming <code>192.168.20.1</code> (pfSense CLIENT)","a":"Lokaal","e":"De gateway zelf ligt in het eigen subnet; dat moet ook, anders kan de client hem niet bereiken."},{"q":"Bestemming <code>192.168.10.1</code> (pfSense SERVER)","a":"Gateway","e":"Ook al is het pfSense: dat adres ligt in 192.168.10.0/24, een ander subnet. Het pakket gaat naar 192.168.20.1."},{"q":"Bestemming <code>8.8.8.8</code>","a":"Gateway","e":"Elk adres buiten 192.168.20.0/24 gaat naar de default gateway."},{"q":"Bestemming <code>192.168.20.200</code> (een andere DHCP-client)","a":"Lokaal","e":"Zelfde netwerkdeel 192.168.20: rechtstreeks. pfSense ziet dit verkeer niet en kan het dus ook niet filteren."},{"q":"Bestemming <code>192.168.21.5</code>","a":"Gateway","e":"Het derde getal verschilt (21 ≠ 20): met /24 is dat een ander netwerk."},{"q":"Bestemming <code>127.0.0.1</code>","a":"Lokaal","e":"Loopback: het pakket verlaat de eigen netwerkstack niet eens. Zeker geen gateway."}]},"interface":{"t":"Op welke interface hoort de regel?","intro":"Regels staan op de interface waar het verkeer pfSense <b>binnenkomt</b>. Netwerk: CLIENT 192.168.20.0/24 (pfSense 192.168.20.1) · SERVER 192.168.10.0/24 (pfSense 192.168.10.1, Windows Server 192.168.10.10). WAN = extern netwerk.","cats":[{"t":"CLIENT","d":"192.168.20.0/24","c":"#EB6008","l":"de interface waar verkeer van clients binnenkomt"},{"t":"SERVER","d":"192.168.10.0/24","c":"#919E2C","l":"de interface waar verkeer van servers binnenkomt"},{"t":"WAN","d":"extern","c":"#000000","l":"de interface waar verkeer van buitenaf binnenkomt"}],"items":[{"q":"Een client opent <code>\\\\SRV01\\Gedeeld</code> (192.168.10.10).","a":"CLIENT","e":"De verbinding start bij de client en komt pfSense binnen via CLIENT."},{"q":"De Windows Server haalt updates van internet.","a":"SERVER","e":"Het verkeer start op 192.168.10.10 en komt binnen via SERVER. (Daar staat standaard ‘allow LAN to any’.)"},{"q":"Een client vraagt <code>nslookup srv01.cursus.local</code> aan 192.168.10.10.","a":"CLIENT","e":"DNS-vraag van de client: binnen via CLIENT. Het antwoord is stateful en heeft geen eigen regel nodig."},{"q":"Een beheerder thuis wil via internet RDP naar de server.","a":"WAN","e":"Verkeer van buitenaf komt via WAN binnen (en heeft daar ook NAT/port forward nodig, wat we níét doen)."},{"q":"Het antwoord van de server op een toegelaten ping van een client.","a":"CLIENT","e":"Strikvraag: het antwoord hoort bij de state van de verbinding die op CLIENT werd toegelaten. Er is geen extra regel nodig, en zeker niet op SERVER."},{"q":"De Windows Server start zelf een RDP-verbinding naar een client.","a":"SERVER","e":"Een nieuwe verbinding die bij de server start, komt binnen via SERVER."},{"q":"Een client surft naar een website op internet.","a":"CLIENT","e":"Het verkeer komt binnen op CLIENT en gaat buiten via WAN; de regel hoort op CLIENT."}]},"rol":{"t":"Wie doet dit bij DHCP-relay?","intro":"Een client in CLIENT vraagt een adres aan bij de Windows DHCP-server op 192.168.10.10, via de relay op pfSense.","cats":[{"t":"Client","d":"Windows-client","c":"#14799B","l":"de client: hij vraagt een configuratie aan en past ze toe"},{"t":"Relay","d":"pfSense","c":"#EB6008","l":"de relay: hij luistert op CLIENT en stuurt door"},{"t":"Server","d":"Windows DHCP","c":"#919E2C","l":"de DHCP-server: hij beheert scopes, kiest het adres en levert de opties"}],"items":[{"q":"Verstuurt de DHCP Discover als broadcast.","a":"Client","e":"De client heeft nog geen adres en kent de server niet: hij roept in zijn eigen subnet."},{"q":"Ontvangt de broadcast op CLIENT en stuurt hem gericht naar 192.168.10.10.","a":"Relay","e":"Dat is precies de relayfunctie: van broadcast naar een gericht (unicast) bericht."},{"q":"Kiest de scope voor 192.168.20.0/24.","a":"Server","e":"De server kiest op basis van het relayadres (192.168.20.1) in de aanvraag."},{"q":"Kiest het vrije adres 192.168.20.100.","a":"Server","e":"Adresbeheer gebeurt alleen op de DHCP-server."},{"q":"Levert optie 003 (router) 192.168.20.1 en optie 006 (DNS) 192.168.10.10.","a":"Server","e":"Scopeopties staan op de Windows DHCP-server."},{"q":"Bezorgt het antwoord van de server terug in het CLIENT-netwerk.","a":"Relay","e":"De server antwoordt aan de relay; pfSense levert het antwoord af op CLIENT."},{"q":"Stelt IP-adres, gateway, DNS-server en suffix in.","a":"Client","e":"De client past de ontvangen lease en opties toe."},{"q":"Mag zelf géén DHCP-server draaien op een interface.","a":"Relay","e":"pfSense kan DHCP-relay en zijn eigen DHCP-server niet tegelijk gebruiken."}]},"laag":{"t":"Welke laag faalt?","intro":"Lees de symptomen en kies de laag die je als eerste onderzoekt. Netwerk: CLIENT 192.168.20.0/24 (pfSense 192.168.20.1) · SERVER 192.168.10.0/24 (pfSense 192.168.10.1, Windows Server 192.168.10.10).","cats":[{"t":"Netwerk","d":"virtueel netwerk of IP","c":"#000000","l":"een fout in de VMnet-koppeling, het IP-adres, het masker of de gateway"},{"t":"Firewall","d":"regel of volgorde","c":"#EB6008","l":"een fout in de pfSense-regels"},{"t":"DHCP","d":"scope of relay","c":"#14799B","l":"een fout in scope, opties of relay"},{"t":"Dienst","d":"DNS, SMB, rechten","c":"#919E2C","l":"een fout in DNS, de dienst of de machtigingen"}],"items":[{"q":"Client met vast adres: <code>arp -a</code> toont <b>geen</b> regel voor 192.168.20.1 en ping geeft Destination host unreachable.","a":"Netwerk","e":"Geen ARP-antwoord = de gateway is lokaal niet bereikbaar: verkeerde VMnet, verkeerd adres of masker."},{"q":"arp -a toont 192.168.20.1 met een MAC-adres, maar elke ping (ook naar 192.168.20.1) geeft Request timed out. Het pfSense-log toont ‘Default deny rule IPv4’ op CLIENT.","a":"Firewall","e":"ARP werkt, dus het lokale netwerk klopt. De blokkering staat in het log."},{"q":"ipconfig /all: Autoconfiguration IPv4 Address 169.254.12.7. Met een vast adres werkte alles.","a":"DHCP","e":"Routing en firewall zijn bewezen met het vaste adres. De lease ontbreekt: scope of relay."},{"q":"Lease 192.168.20.105, ping 192.168.10.10 lukt, <code>nslookup srv01.cursus.local</code> geeft een time-out. DNS Servers: 192.168.10.1.","a":"DHCP","e":"De client kreeg een foute DNS-server via optie 006. De oorzaak zit in de scope, niet in de DNS-dienst."},{"q":"Ping, nslookup en poort 445 lukken. <code>\\\\SRV01\\Gedeeld</code> geeft ‘Access is denied’.","a":"Dienst","e":"Het netwerkpad is bewezen; nu machtigingen (share en NTFS) en het gebruikte account."},{"q":"ipconfig /all: 192.168.10.150, geen gateway, DHCP Server 192.168.10.10. Verwacht was 192.168.20.x.","a":"Netwerk","e":"De client hangt aan het SERVER-netwerk (VMnet2): verkeerde virtuele koppeling."},{"q":"Ping 192.168.10.10 lukt, poort 53 lukt, poort 445 geeft False. Een collega maakte vanochtend een regel ‘onderhoud’ bovenaan op CLIENT.","a":"Firewall","e":"Regels werken van boven naar beneden: een blokkeerregel bovenaan wint."},{"q":"De relay staat aan met upstream 192.168.10.10, maar alleen SERVER is als downstream geselecteerd. Clients krijgen 169.254-adressen.","a":"DHCP","e":"De relay luistert niet op CLIENT, waar de broadcasts ontstaan."}]}},
"intros":{"sorteer":{"t":"Sorteer","p":["Je krijgt een situatie en kiest de categorie die past.","Bij een fout zie je waarom je keuze minder past én waarom het juiste antwoord past."],"cs":"routing"},"ontwerp":{"t":"Ontwerp het netwerk","p":["Stap 1: vul het adresplan in. De tekening toont welke waarde gevraagd wordt.","Stap 2: vier vragen over het ontwerp, telkens met een tekening."],"cs":"plan"},"pakket":{"t":"Volg het pakket","p":["Stap 1: zet de weg van een ping van de client naar de server in volgorde.","Stap 2: zet de DHCP-relay in volgorde.","Stap 3: vier vragen."],"cs":"relay"},"regel":{"t":"Lees de regel","p":["Elke vraag toont firewallregels zoals in pfSense. Lees interface, actie, bron, bestemming, poort en volgorde.","Denk eraan: de eerste regel die past, beslist. Past er geen enkele, dan blokkeert de verborgen ‘Default deny’."],"cs":"regels"},"uitvoer":{"t":"Lees de uitvoer","p":["Je ziet echte uitvoer van ipconfig, ping, arp, Test-NetConnection of het pfSense-log.","Wat bewijst die uitvoer, en wat niet?"],"cs":"cmd"},"bewijs":{"t":"Welk bewijs is overtuigend?","p":["Een collega trekt een conclusie uit één test. Klopt dat?","Eén test bewijst één laag."],"cs":"ladder"},"exit1":{"t":"Exitcheck blok 1","p":["Vijf vragen over segmentatie, het ontwerp en pfSense.","Maak ze alleen. Je docent bekijkt straks samen met de klas de moeilijkste."],"cs":"plan"},"exit2":{"t":"Exitcheck blok 2","p":["Vijf vragen over firewallregels, diensten testen en DHCP-relay."],"cs":"relay"},"demo":{"t":"Voorspel de demo","p":["Kies vóór elke demo je voorspelling. Na de demo toon je het bewijs en zie je of je juist zat.","Je mag je keuze wijzigen zolang het bewijs niet getoond is."],"cs":"ladder"},"status":{"t":"Status","p":["Kies je status en leg je gsm met het scherm naar boven naast je laptop.","De docent ziet zo wie hulp nodig heeft. Bij 3 (probleem) schrijf je eerst verwachting, test en resultaat op."],"cs":"ladder"},"fout":{"t":"Breek het bij je buur","p":["Alleen als jouw omgeving volledig werkt (fase 2 klaar).","Saboteur: trek een foutkaart en voer de fout uit bij je buur (2 min, buur kijkt weg). Slachtoffer: vul het ticket in en los op met de diagnoseladder.","Na 10 min vast? De saboteur toont de laag als hint."],"cs":"ladder"},"ticket":{"t":"Ticketformulier","p":["Werk een melding af als een systeembeheerder: feiten, verwacht gedrag, bewijs per laag, hypothese, oplossing en nacontrole."],"cs":"ladder"},"werkdoel":{"t":"Werkdoel en bewijslijst","p":["Schrijf vóór je begint wat je per fase moet aantonen en met welke test.","Kopieer of download het en plak het in je verslag."],"cs":"opdracht"},"exitticket":{"t":"Exit ticket","p":["Vier korte vragen en één open vraag om af te sluiten."],"cs":"plan"}},
"infoTip":"Twijfel je? Tik rechtsboven op <b>ⓘ Info</b>. Daar vind je de theorie en de labomgeving. Dat is geen spieken: ook een systeembeheerder zoekt dingen op in de documentatie.",
"cheat":[{"id":"plan","t":"Labomgeving en adresplan","h":"\n<table><tr><th>Onderdeel</th><th>Adres</th><th>Functie</th></tr>\n<tr><td>SERVER-netwerk (VMnet2)</td><td><code>192.168.10.0/24</code></td><td>servers</td></tr>\n<tr><td>pfSense SERVER</td><td><code>192.168.10.1</code></td><td>gateway van de server</td></tr>\n<tr><td>SRV01</td><td><code>192.168.10.10</code></td><td>AD DS, DNS, DHCP, share <code>\\\\SRV01\\Gedeeld</code></td></tr>\n<tr><td>CLIENT-netwerk (VMnet3)</td><td><code>192.168.20.0/24</code></td><td>clients</td></tr>\n<tr><td>pfSense CLIENT</td><td><code>192.168.20.1</code></td><td>gateway van de clients</td></tr>\n<tr><td>DHCP-bereik</td><td><code>192.168.20.100–200</code></td><td>scope CLIENT-NETWERK</td></tr>\n<tr><td>WAN (VMnet8)</td><td>via DHCP</td><td>internet via NAT</td></tr></table>\n<p>Domein <code>cursus.local</code> (CURSUS\\). Client: <b>CLIENT01</b>, tijdelijk statisch <code>192.168.20.100</code>. De cursus schrijft ‘domeinnaam.local’, ‘servernaam’ en ‘gedeeldemap’: in ons labo is dat <code>cursus.local</code>, <code>SRV01</code> en <code>Gedeeld</code>.</p>"},{"id":"routing","t":"Subnet, gateway, firewall","h":"\n<p><b>Subnet</b>: toestellen met hetzelfde netwerkdeel (na het masker) praten rechtstreeks. <b>Default gateway</b>: waar verkeer naar een ander subnet naartoe gaat; moet in het eigen subnet liggen. <b>Firewall</b>: beslist of verkeer mag.</p>\n<p><b>Routering ≠ firewalling.</b> pfSense kan de weg naar SERVER kennen en het verkeer toch blokkeren.</p>\n<p>Zo beslist een client: vergelijk bestemming met eigen adres + masker. Zelfde netwerk → rechtstreeks (ARP). Ander netwerk → naar de gateway.</p>"},{"id":"pfsense","t":"pfSense in het kort","h":"\n<p><b>Installatie (CE 2.8)</b>: de Netgate Installer downloadt de software via WAN (internet nodig). Daarna het installatiemedium loskoppelen.</p>\n<p><b>Console</b>: 1) Assign Interfaces (WAN, LAN, OPT1 kiezen op MAC-adres) · 2) Set interface(s) IP address (geen upstream gateway op LAN/OPT1; DHCP-server: n).</p>\n<p><b>Webinterface</b>: <code>https://192.168.10.1</code> vanuit SERVER, admin / pfsense bij de eerste aanmelding. Interfaces › LAN/OPT1 › Description = SERVER / CLIENT.</p>\n<p><b>Standaardregels</b>: LAN (SERVER) heeft een anti-lockoutregel en ‘Default allow LAN to any’. OPT1 (CLIENT) heeft <b>geen</b> regels: alles wat binnenkomt, valt op de verborgen Default deny, ook ping naar 192.168.20.1.</p>"},{"id":"regels","t":"Firewallregels","h":"\n<p>Een regel = <b>actie</b> (Pass/Block) · <b>interface</b> · <b>protocol</b> · <b>bron</b> · <b>bestemming</b> · <b>poort</b>.</p>\n<ul><li>Regel op de interface waar het verkeer <b>binnenkomt</b> (clientverkeer → CLIENT).</li>\n<li>Van <b>boven naar beneden</b>: de eerste passende regel beslist; past er geen, dan Default deny.</li>\n<li><b>Stateful</b>: het antwoord op een toegelaten verbinding mag automatisch terug.</li>\n<li><b>Save + Apply Changes</b>: pas na toepassen is een regel actief.</li>\n<li>Bron <b>CLIENT subnets</b> (cursus: ‘CLIENT net’) = heel 192.168.20.0/24.</li></ul>\n<p>Tijdelijke regel: Pass · IPv4 · Any · CLIENT subnets → any · ‘TEMP - volledige toegang tijdens configuratie’.</p>"},{"id":"relay","t":"DHCP over subnetten","h":"\n<p>DHCP start met een <b>broadcast</b> (Discover). Een router stuurt broadcasts niet door → zonder relay krijgt de client APIPA (169.254.x.x).</p>\n<p><b>DHCP-relay</b> (pfSense › Services › DHCP Relay): luistert op de <b>downstream</b>-interface CLIENT en stuurt gericht naar de <b>upstream</b>-server 192.168.10.10. De relay zet zijn adres 192.168.20.1 in de aanvraag; zo kiest de server de juiste scope. De relay deelt zelf niets uit. De DHCP-server van pfSense moet uit staan.</p>\n<p><b>Scope CLIENT-NETWERK</b>: 192.168.20.100–200 · /24 · 003 Router 192.168.20.1 · 006 DNS 192.168.10.10 · 015 DNS-domein cursus.local.</p>"},{"id":"cmd","t":"Commando's","h":"\n<table><tr><th>Commando</th><th>Bewijst</th></tr>\n<tr><td><code>ipconfig /all</code></td><td>adres, masker, gateway, DNS, suffix, DHCP Server</td></tr>\n<tr><td><code>ping 127.0.0.1</code></td><td>eigen TCP/IP-stack</td></tr>\n<tr><td><code>arp -a</code></td><td>lokaal bereikbare toestellen (MAC-adres): de gateway zit op hetzelfde netwerk</td></tr>\n<tr><td><code>ping 192.168.10.10</code></td><td>ICMP over de grens (TTL 127 = één router)</td></tr>\n<tr><td><code>nslookup srv01.cursus.local 192.168.10.10</code></td><td>naamresolutie bij die server</td></tr>\n<tr><td><code>Test-NetConnection 192.168.10.10 -Port 445</code></td><td>één TCP-poort (53 = DNS, 445 = SMB)</td></tr>\n<tr><td><code>ipconfig /release</code> · <code>/renew</code></td><td>nieuwe lease aanvragen</td></tr>\n<tr><td><code>Test-ComputerSecureChannel</code></td><td>vertrouwensrelatie met het domein</td></tr>\n<tr><td><code>Get-DhcpServerv4Scope</code> · <code>Get-DhcpServerv4Lease -ScopeId 192.168.20.0</code></td><td>scopes en leases op de server</td></tr>\n<tr><td>pfSense › Status › System Logs › Firewall</td><td>wat werd waar toegelaten of geblokkeerd</td></tr></table>"},{"id":"ladder","t":"Diagnoseladder","h":"\n<p><b>Virtueel netwerk → IP-configuratie → Firewall → Servergateway → DHCP-scope → DHCP-relay → DNS → Poort → Toepassing</b></p>\n<p>Werk van dichtbij naar veraf en <b>stop bij de eerste mislukte test</b>. Wijzig één ding tegelijk.</p>\n<p>Een goede hulpvraag: <i>verwachting · test · exacte uitvoer · wat ik al uitsloot</i>. Bv. ‘De client krijgt 192.168.20.115/24 en bereikt 192.168.20.1, maar niet 192.168.10.10. De CLIENT-regel is toegepast. Welke serverzijde controleer ik nu?’</p>"},{"id":"opdracht","t":"Opdracht namiddag","h":"\n<p><b>Fase 1</b>: VMnets, pfSense (drie interfaces), SRV01 met gateway 192.168.10.1, CLIENT01 statisch 192.168.20.100, testregel op CLIENT. Stop pas als 192.168.20.1, 192.168.10.1 en 192.168.10.10 antwoorden.</p>\n<p><b>Fase 2</b>: scope CLIENT-NETWERK, relay (CLIENT → 192.168.10.10), client automatisch, volledige lease, DNS, poort 53 en 445, share via naam.</p>\n<p><b>Verfijnen</b>: gerichte regels (DNS, SMB, domeindiensten, ICMP naar 192.168.10.10), testen, dan TEMP uitschakelen en opnieuw testen.</p>\n<p><b>Bewijsstukken</b>: interfaceoverzicht · serverconfiguratie · regel op CLIENT · scope en opties · relay · ipconfig /all · DNS-test · share via naam. Bij elk bewijs één zin: wat het aantoont.</p>"},{"id":"waarom","t":"Waarom…?","h":"<h3>De bestaande omgeving</h3><p><b>Waarom werkte alles al zonder router?</b><br>Server en client zaten in hetzelfde subnet. Lokaal verkeer gaat rechtstreeks via de switch; de gateway wordt alleen gebruikt voor andere netwerken.</p><p><b>Waarom zouden we iets veranderen dat werkt?</b><br>Omdat niets het verkeer tussen clients en servers controleert. Een besmette of misbruikte client kan alles op de server aanspreken.</p><h3>Segmentatie</h3><p><b>Waarom niet gewoon de Windows Firewall op de server gebruiken?</b><br>Die blijft nuttig, maar beschermt één toestel. Een netwerkfirewall regelt centraal wat tussen hele netwerken mag, en logt dat op één plaats.</p><p><b>Waarom is segmentatie geen volledige isolatie?</b><br>Clients moeten de server nog gebruiken. Het verkeer gaat alleen via een controlepunt dat beslist wat mag.</p><p><b>Waarom helpt een kleiner broadcastdomein?</b><br>Broadcasts bereiken alle toestellen in het subnet. Minder toestellen per subnet betekent minder ruis en een fout of aanval blijft beperkter.</p><h3>Lokaal of gateway</h3><p><b>Waarom gebruikt de client de gateway niet voor 192.168.20.120?</b><br>Met zijn masker /24 ziet hij dat 192.168.20.120 in zijn eigen netwerk ligt. Dan zoekt hij met ARP het MAC-adres en stuurt rechtstreeks.</p><p><b>Waarom kan pfSense een route kennen en het verkeer toch blokkeren?</b><br>Routeren beslist waarheen, de firewall beslist óf het mag. Het zijn twee aparte stappen.</p><h3>Ontwerp</h3><p><b>Waarom krijgt de server een vast adres en de client niet?</b><br>Iedereen moet de diensten van de server altijd op hetzelfde adres vinden (DNS, DHCP-relay). Clients mogen wisselen; DHCP houdt bij wie wat heeft.</p><p><b>Waarom mag de DNS-server in een ander subnet staan, maar de gateway niet?</b><br>De DNS-server bereik je via de gateway. De gateway zelf moet rechtstreeks bereikbaar zijn: hij is de eerste stap naar buiten.</p><p><b>Waarom .1 voor pfSense?</b><br>Een afspraak: de router krijgt het eerste adres. Dat maakt fouten sneller zichtbaar. Technisch mag elk vrij adres.</p><h3>Virtuele netwerken</h3><p><b>Waarom zetten we VMware-DHCP uit op VMnet2 en VMnet3?</b><br>Anders deelt VMware zelf adressen uit. Dan antwoorden er twee DHCP-servers en krijgt de client misschien een verkeerde configuratie.</p><p><b>Waarom de hostadapter uit?</b><br>Die krijgt standaard .1 en botst met pfSense. Bovendien zou je laptop dan zelf in SERVER en CLIENT zitten, langs de firewall heen.</p><p><b>Waarom VMnet8 voor WAN?</b><br>NAT geeft pfSense internet via je laptop, zonder dat je labo zichtbaar is op het HOGENT-netwerk. De installer heeft internet nodig.</p><h3>pfSense installeren</h3><p><b>Waarom heeft de installer internet nodig?</b><br>pfSense CE 2.8 gebruikt de Netgate Installer: die downloadt de software tijdens de installatie. Daarom moet WAN eerst werken.</p><p><b>Waarom het installatiemedium loskoppelen?</b><br>Anders start de VM opnieuw in de installer in plaats van vanaf de schijf.</p><p><b>Waarom drie netwerkkaarten en geen VLAN's?</b><br>VLAN's laten meerdere netwerken over één kabel lopen. Dat is een volgende stap; drie kaarten maken het nu zichtbaar en eenvoudig.</p><h3>Interfaces toewijzen</h3><p><b>Waarom niet gewoon de volgorde van VMware volgen?</b><br>Die volgorde is niet gegarandeerd dezelfde in pfSense. Het MAC-adres is de enige zekere koppeling.</p><p><b>Waarom heten ze eerst LAN en OPT1?</b><br>Dat zijn de standaardnamen van pfSense. We hernoemen ze, zodat regels en logs meteen leesbaar zijn.</p><h3>Adresseren</h3><p><b>Waarom geen gateway op SERVER en CLIENT?</b><br>pfSense heeft zelf een adres in die netwerken: het kent ze rechtstreeks. Een upstream gateway is alleen nodig richting internet (WAN).</p><p><b>Waarom de DHCP-server van pfSense niet aanzetten?</b><br>De Windows DHCP-server blijft centraal (scopes, AD-integratie). En pfSense kan geen relay draaien zolang zijn eigen DHCP-server aan staat.</p><h3>Webinterface</h3><p><b>Waarom openen we de webinterface vanaf SRV01?</b><br>Alleen vanuit SERVER is de webinterface standaard bereikbaar (anti-lockoutregel). SRV01 heeft een browser en staat al in dat netwerk.</p><p><b>Waarom krijgen we een certificaatwaarschuwing?</b><br>pfSense gebruikt een zelfondertekend certificaat. In het labo aanvaarden we het; in productie installeer je een vertrouwd certificaat.</p><h3>Servergateway</h3><p><b>Waarom heeft de server nu wel een gateway nodig?</b><br>Om clients in 192.168.20.0/24 te antwoorden. Zonder gateway weet de server niet hoe hij een ander subnet bereikt.</p><p><b>Waarom gebruikt de DC zichzelf als DNS?</b><br>Zijn domeinrecords (SRV-records, cursus.local) staan op zijn eigen DNS-server. pfSense kent die niet.</p><h3>Client verplaatsen</h3><p><b>Waarom eerst een statisch adres?</b><br>Eén probleem tegelijk: zo test je virtueel netwerk, gateway en firewall zonder dat DHCP en relay meespelen.</p><p><b>Waarom de VM afsluiten voor je de VMnet wijzigt?</b><br>Zo start Windows proper op het nieuwe netwerk en krijg je geen half-oude netwerkstatus.</p><p><b>Waarom antwoordt de gateway niet, terwijl de cursus zegt dat hij moet antwoorden?</b><br>Op CLIENT staan in pfSense nog geen regels; alles wat binnenkomt wordt geblokkeerd, ook ping naar pfSense zelf. ARP werkt wel: dat bewijst de lokale verbinding.</p><h3>Testen</h3><p><b>Waarom stoppen bij de eerste mislukte test?</b><br>Alles wat verder ligt, hangt ervan af. Als de gateway niet werkt, zegt een DNS-test niets extra.</p><p><b>Waarom bewijst een mislukte ping niet dat routing fout is?</b><br>Een firewall kan ICMP blokkeren terwijl het pad perfect werkt. Combineer met configuratie en logs.</p><h3>Firewallregels</h3><p><b>Waarom staat de regel op CLIENT en niet op SERVER?</b><br>pfSense controleert een regel wanneer het verkeer de firewall binnenkomt. Clientverkeer komt binnen via CLIENT.</p><p><b>Waarom hoeft er geen regel voor het antwoord van de server?</b><br>pfSense is stateful: het onthoudt toegelaten verbindingen en laat het bijbehorende antwoord automatisch terug.</p><p><b>Waarom ‘CLIENT subnets’ en niet 192.168.20.100?</b><br>De client krijgt straks via DHCP een ander adres. De subnetbron blijft dan kloppen.</p><h3>Any-any-regel</h3><p><b>Waarom eerst alles openzetten? Dat is toch onveilig?</b><br>Tijdelijk, om de firewall als oorzaak uit te sluiten. Pas als alles werkt, maak je gerichte regels en schakel je deze uit.</p><p><b>Waarom ‘Apply Changes’ apart?</b><br>Zo kan je meerdere wijzigingen voorbereiden en in één keer actief maken. Vergeten toepassen = regel bestaat, maar werkt niet.</p><p><b>Waarom is de TTL nu 127?</b><br>Windows start met 128; elke router verlaagt met 1. pfSense zit ertussen.</p><h3>Diensten testen</h3><p><b>Waarom niet alleen pingen?</b><br>Ping test alleen ICMP. DNS (53), SMB (445) en machtigingen kunnen elk afzonderlijk falen.</p><p><b>Waarom eerst via IP, dan via naam?</b><br>Dan weet je of een fout in het netwerkpad of in DNS zit.</p><h3>DHCP over subnetten</h3><p><b>Waarom stuurt de client een broadcast?</b><br>Hij heeft nog geen adres en kent het adres van de DHCP-server niet. Een broadcast bereikt iedereen in het eigen subnet.</p><p><b>Waarom stuurt pfSense de broadcast niet gewoon door?</b><br>Routers stoppen broadcasts aan de subnetgrens. Anders zou elke broadcast door het hele netwerk vloeien.</p><h3>DHCP-relay</h3><p><b>Waarom niet gewoon de DHCP-server van pfSense gebruiken?</b><br>Dan heb je twee plaatsen met adresbeheer. Met relay blijft alles centraal op de Windows-server, ook voor extra subnetten.</p><p><b>Hoe weet de server welke scope hij moet gebruiken?</b><br>De relay zet zijn eigen adres op CLIENT (192.168.20.1) in de aanvraag (veld giaddr). De server kiest de scope die bij dat subnet hoort.</p><h3>CLIENT-scope</h3><p><b>Waarom is optie 003 192.168.20.1 en niet het adres van de server?</b><br>De gateway moet in het eigen subnet liggen en routeren. De server deelt adressen uit maar routeert niet.</p><p><b>Waarom .100–.200?</b><br>Lage adressen blijven vrij voor de router en vaste toestellen; zo overlappen ze nooit met DHCP.</p><h3>Relay instellen</h3><p><b>Waarom alleen CLIENT als downstream?</b><br>Daar ontstaan de aanvragen. Op SERVER staat de DHCP-server zelf; die broadcasts hoeven niet doorgestuurd te worden.</p><p><b>Waarom staat bij DHCP Server 192.168.10.10?</b><br>Die server gaf de lease. De relay transporteert alleen.</p><h3>Minimale toegang</h3><p><b>Waarom niet gewoon de any-any-regel laten staan als alles werkt?</b><br>Dan kan elke client alles bereiken, ook de firewall zelf en internet. Minimale toegang beperkt de schade bij een probleem op één client.</p><p><b>Waarom zijn er voor het domein zoveel poorten nodig?</b><br>Aanmelden en groepsbeleid gebruiken meerdere diensten: DNS, Kerberos, LDAP, SMB, RPC en tijd. Daarom groeperen we ze in een alias.</p><p><b>Waarom eerst de gerichte regels testen en dan pas de brede uitschakelen?</b><br>Anders weet je niet of een test lukt dankzij de nieuwe regel of nog dankzij de brede.</p><h3>Opleveren</h3><p><b>Waarom geen screenshots van tijdelijke instellingen?</b><br>De documentatie moet de werkende eindtoestand tonen; anders herstelt een collega de verkeerde configuratie.</p><p><b>Waarom bij elk bewijsstuk een zin uitleg?</b><br>Een screenshot toont iets, maar niet wat het bewijst of wat je verwachtte.</p>"}],
"ontwerp":{"svg":{"c":"?client","s":"192.168.10.10/24","pc":"?pfc","ps":"?pfs","sgw":"?sgw","cgw":"?cgw","cdns":"?cdns"},"fields":[{"k":"pfs","l":"pfSense SERVER-interface","o":["192.168.10.1/24","192.168.20.1/24","192.168.10.10/24","192.168.1.1/24"],"a":"192.168.10.1/24","x":"Een adres uit het SERVER-subnet; volgens het plan krijgt de router .1.","why":{"192.168.20.1/24":"dat subnet hoort bij CLIENT.","192.168.10.10/24":"dat is het vaste adres van de Windows Server.","192.168.1.1/24":"dat is de standaard van pfSense, maar het past niet in ons SERVER-subnet."}},{"k":"pfc","l":"pfSense CLIENT-interface","o":["192.168.20.1/24","192.168.10.1/24","192.168.20.100/24","192.168.20.1/16"],"a":"192.168.20.1/24","x":"Eén adres in het CLIENT-subnet, met hetzelfde masker als de clients.","why":{"192.168.10.1/24":"dan zitten beide interfaces in hetzelfde subnet: dat mag niet.","192.168.20.100/24":"dat is het eerste adres van de DHCP-pool.","192.168.20.1/16":"/16 overlapt met 192.168.10.0/24 (ook 192.168.x.x)."}},{"k":"sgw","l":"Default gateway van de Windows Server","o":["192.168.10.1","192.168.20.1","192.168.10.10","geen"],"a":"192.168.10.1","x":"De pfSense-interface in het eigen subnet van de server.","why":{"192.168.20.1":"dat adres ligt niet in het subnet van de server: niet rechtstreeks bereikbaar.","192.168.10.10":"dat is de server zelf.","geen":"dan kan de server clients in 192.168.20.0/24 niet antwoorden."}},{"k":"cgw","l":"Default gateway van de client","o":["192.168.20.1","192.168.10.1","192.168.10.10","192.168.20.100"],"a":"192.168.20.1","x":"De pfSense-interface in het eigen subnet van de client.","why":{"192.168.10.1":"ligt buiten 192.168.20.0/24: de client kan dat adres niet rechtstreeks bereiken.","192.168.10.10":"de server routeert niet en ligt in een ander subnet.","192.168.20.100":"dat is een clientadres."}},{"k":"cdns","l":"DNS-server van de client","o":["192.168.10.10","192.168.20.1","192.168.10.1","8.8.8.8"],"a":"192.168.10.10","x":"De Windows DNS-server (DC): alleen die kent cursus.local. Hij mag in een ander subnet staan.","why":{"192.168.20.1":"pfSense kent de domeinrecords van cursus.local niet.","192.168.10.1":"pfSense kent de domeinrecords niet.","8.8.8.8":"een publieke DNS-server kent cursus.local niet: aanmelden in het domein faalt."}},{"k":"client","l":"DHCP-bereik voor clients","o":["192.168.20.100–192.168.20.200","192.168.10.100–192.168.10.200","192.168.20.1–192.168.20.254","192.168.20.0–192.168.20.255"],"a":"192.168.20.100–192.168.20.200","x":"Een bereik in het CLIENT-subnet dat de router (.1) en vaste adressen niet bevat.","why":{"192.168.10.100–192.168.10.200":"dat is het SERVER-subnet.","192.168.20.1–192.168.20.254":"dan zou DHCP ook .1, het adres van pfSense, kunnen uitdelen.","192.168.20.0–192.168.20.255":".0 is het netwerkadres en .255 het broadcastadres."}}],"q":[{"s":"<b>Situatie</b><br>De Windows Server en de client hebben verschillende subnetten (192.168.10.0/24 en 192.168.20.0/24) gekregen, maar hangen allebei aan <b>VMnet2</b>.","svg":{"c":"192.168.20.100/24","s":"192.168.10.10/24","vc":"VMnet2","vs":"VMnet2","same":1},"q":"Wat is het probleem met deze opstelling?","o":["Geen echte scheiding: ze delen dezelfde virtuele switch en hetzelfde broadcastdomein","Geen probleem: verschillende subnetten scheiden het verkeer al voldoende, ook op één switch","De server verliest zijn vaste adres en krijgt een APIPA-adres","pfSense kan nu geen WAN-verbinding meer maken via VMnet8"],"a":0,"w":[null,"Wie zijn eigen adres wijzigt, kan meteen rechtstreeks praten; broadcasts (zoals DHCP) bereiken elkaar nog.","Een vast adres verdwijnt niet door de VMnet-keuze.","WAN hangt aan VMnet8; dat staat hier los van."],"e":"Segmentatie moet ook op de hypervisor: SERVER en CLIENT op aparte VMnets, alleen pfSense in beide."},{"s":"<b>Situatie</b><br>Een client krijgt 192.168.20.115/24.","svg":{"c":"192.168.20.115/24","cgw":"?","cdns":"?"},"q":"Welke gateway en DNS-server moet deze client gebruiken?","o":["Gateway 192.168.20.1 · DNS 192.168.10.10","Gateway 192.168.10.1 · DNS 192.168.10.10","Gateway 192.168.20.1 · DNS 192.168.20.1","Gateway 192.168.10.10 · DNS 192.168.10.10"],"a":0,"w":[null,"192.168.10.1 ligt niet in het subnet van de client.","pfSense kent de records van cursus.local niet.","De server routeert niet en ligt in een ander subnet."],"e":"De gateway moet in het eigen subnet liggen; de DNS-server bereik je via die gateway."},{"s":"<b>Situatie</b><br>Het ontwerp gebruikt voor CLIENT 192.168.20.0/24. Iemand stelt voor om de CLIENT-interface 192.168.20.1/<b>16</b> te geven, ‘dan is er meer plaats’.","svg":{"pc":"192.168.20.1/16","ps":"192.168.10.1/24"},"q":"Waarom is dat een slecht idee?","o":["/16 omvat ook 192.168.10.0/24: CLIENT en SERVER overlappen","Een /16-masker kan je niet instellen op een virtuele netwerkkaart","Met een /16-masker werkt de DHCP-relay van pfSense niet meer","Een groter subnet is altijd trager door meer broadcastverkeer"],"a":0,"w":[null,"Een masker is gewoon een instelling; dat kan op elke kaart.","Het probleem is ruimer: pfSense weet niet meer aan welke kant 192.168.10.10 ligt.","Snelheid hangt niet af van het masker."],"e":"/16 betekent 192.168.0.0–192.168.255.255. Daar valt ook het SERVER-netwerk in. Interfaces mogen geen overlappende subnetten hebben."},{"s":"<b>Situatie</b><br>De Windows Server (192.168.10.10/24) heeft als gateway 192.168.10.1 ingesteld, maar als voorkeurs-DNS-server ook <b>192.168.10.1</b> (pfSense).","svg":{"sdns":"192.168.10.1"},"q":"Wat gaat er waarschijnlijk mis?","o":["De DC vindt zijn eigen domeinrecords niet meer: aanmelden en DC-zoeken falen","De server kan pfSense niet meer pingen omdat ping DNS nodig heeft","De server verliest zijn IP-adres bij de volgende herstart","Niets: pfSense stuurt alle DNS-vragen door naar de juiste zone, ook die van cursus.local"],"a":0,"w":[null,"Ping gebruikt geen DNS.","Het adres is statisch.","pfSense stuurt door naar zijn eigen (internet-)DNS-servers, niet naar de zone cursus.local op de DC."],"e":"Een domeincontroller gebruikt zichzelf als DNS-server: daar staan de SRV-records van het domein."}]},
"pakket":{"ping":["De client vergelijkt 192.168.10.10 met zijn eigen adres en masker: ander subnet","De client stuurt het pakket naar zijn gateway 192.168.20.1","Het pakket komt pfSense binnen via CLIENT","pfSense controleert de regels op CLIENT","pfSense routeert het pakket via SERVER naar 192.168.10.10","De server antwoordt via zijn gateway 192.168.10.1; pfSense herkent de state"],"relay":["De client stuurt een DHCP Discover als broadcast in CLIENT","pfSense ontvangt de broadcast op de downstream-interface CLIENT","De relay stuurt de aanvraag gericht naar 192.168.10.10, met zijn adres 192.168.20.1 erin","De Windows DHCP-server kiest de scope voor 192.168.20.0/24","Het antwoord gaat terug via pfSense naar de client","De client past adres, gateway, DNS-server en suffix toe"],"q":[{"s":"<b>Situatie</b><br>pfSense heeft een regel <i>Pass · bron CLIENT subnets · bestemming any</i> op CLIENT. De Windows Server (192.168.10.10) heeft <b>geen default gateway</b>.","svg":{"sgw":"geen","rule":"CLIENT","x":"s"},"q":"Een client pingt 192.168.10.10. Wat gebeurt er?","o":["Het verzoek komt aan, maar het antwoord niet terug: time-out","Reply: de regel op CLIENT laat al het verkeer toe","Destination host unreachable, gemeld door de client zelf","pfSense blokkeert het verzoek al op de CLIENT-interface"],"a":0,"w":[null,"De regel laat het verzoek door; het probleem zit in de terugweg.","De gateway van de client werkt: die melding zie je hier niet.","De regel op CLIENT laat het verzoek toe."],"e":"De server weet niet hoe hij 192.168.20.0/24 bereikt zonder gateway. Kijk altijd naar beide richtingen."},{"s":"<b>Situatie</b><br>Een client in 192.168.20.0/24 krijgt een APIPA-adres. Op de Windows DHCP-server staat een actieve scope voor 192.168.20.0/24. Op pfSense staat de DHCP-relay <b>uit</b>.","svg":{"c":"169.254.x.x","x":"pc"},"q":"Waar stopt de DHCP Discover?","o":["Aan de CLIENT-interface: broadcasts worden niet gerouteerd","Op de server: de scope voor CLIENT is nog niet geautoriseerd","In de firewall: er is geen regel voor UDP-poort 67","Bij de client: zonder IP-adres verstuurt hij niets"],"a":0,"w":[null,"Daar geeft de situatie geen aanwijzing voor; bovendien bereikt de aanvraag de server niet eens.","Zelfs met een regel stuurt een router een broadcast niet door.","Een client zonder adres verstuurt wel degelijk een Discover, vanaf 0.0.0.0."],"e":"Een broadcast blijft in zijn eigen subnet. Zonder relay komt de Discover nooit in SERVER."},{"s":"<b>Situatie</b><br>De relay stuurt aanvragen van CLIENT naar 192.168.10.10. Op de server bestaat alleen een scope voor <b>192.168.10.0/24</b>.","q":"Krijgt een client in CLIENT een bruikbare lease?","o":["Nee: zonder scope voor 192.168.20.0/24 biedt de server niets aan","Ja: hij krijgt een adres uit de enige scope die bestaat, 192.168.10.0/24","Ja: de relay vult zelf een adres uit 192.168.20.0/24 in","Ja, alleen zonder gateway omdat optie 003 ontbreekt"],"a":0,"w":[null,"De server kiest de scope op basis van het relayadres 192.168.20.1; een adres uit een ander subnet zou bovendien onbruikbaar zijn.","De relay deelt niets uit.","Er komt geen lease."],"e":"Relay brengt de aanvraag ter plaatse; de server moet ook een scope voor dat subnet hebben."},{"s":"<b>Situatie</b><br>Een client pingt de Windows Server. De regel op CLIENT laat het toe. Op SERVER staat <b>geen</b> regel die verkeer naar CLIENT toelaat.","q":"Mag het antwoord (echo reply) van de server terug naar de client?","o":["Ja: het hoort bij een toegelaten verbinding in de state table","Nee: daarvoor is een extra regel op SERVER nodig, van 192.168.10.10 naar CLIENT","Nee: antwoorden van servers worden altijd geblokkeerd","Alleen als de regel op CLIENT ‘bidirectioneel’ is"],"a":0,"w":[null,"Stateful firewalling maakt die extra regel overbodig.","Antwoorden op toegelaten verbindingen mogen terug.","Zo'n instelling bestaat niet: dat is net wat stateful doet."],"e":"pfSense is stateful: het onthoudt de verbinding en laat het bijbehorende antwoord automatisch door."}]},
"regel":[{"s":"<b>Situatie</b><br>Regels op <b>CLIENT</b>:<table class='rules'><tr><th>#</th><th>Actie</th><th>Proto</th><th>Bron</th><th>Bestemming</th><th>Poort</th><th>Beschrijving</th></tr><tr class='pass'><td>1</td><td>Pass</td><td>Any</td><td>CLIENT subnets</td><td>any</td><td>*</td><td>TEMP - volledige toegang</td></tr></table>","q":"Wat laat deze regel toe?","o":["Alle IPv4-verkeer dat vanuit CLIENT binnenkomt, naar elke bestemming","Alleen verkeer dat de server naar de clients stuurt","Alleen ping (ICMP) van de clients naar elke bestemming","Alle verkeer op alle interfaces van pfSense samen, omdat de bron ‘any’ is"],"a":0,"w":[null,"Dat komt binnen via SERVER; deze regel staat op CLIENT.","Protocol Any omvat TCP, UDP en ICMP.","Een regel geldt alleen op de interface waar hij staat."],"e":"Interface CLIENT, bron CLIENT subnets, bestemming any, protocol any: alles wat de clients beginnen."},{"s":"<b>Situatie</b><br>Regels op <b>SERVER</b>:<table class='rules'><tr><th>#</th><th>Actie</th><th>Proto</th><th>Bron</th><th>Bestemming</th><th>Poort</th><th>Beschrijving</th></tr><tr class='pass'><td>1</td><td>Pass</td><td>Any</td><td>CLIENT subnets</td><td>192.168.10.10</td><td>*</td><td>clients naar server</td></tr></table>Op CLIENT staan geen regels.","q":"Een client pingt 192.168.10.10. Wat gebeurt er?","o":["Geblokkeerd: het komt binnen op CLIENT en daar past niets","Toegelaten: bron en bestemming van de regel kloppen","Toegelaten, maar het antwoord van de server komt niet terug","Toegelaten, omdat SERVER standaard alles doorlaat"],"a":0,"w":[null,"Bron en bestemming kloppen, maar de regel staat op de verkeerde interface.","Het verzoek komt niet eens door.","SERVER laat alleen toe wat er binnenkomt op SERVER."],"e":"Regels worden gecontroleerd op de interface waar het verkeer binnenkomt: CLIENT. Daar valt het op de Default deny."},{"s":"<b>Situatie</b><br>Regels op <b>CLIENT</b>, van boven naar beneden:<table class='rules'><tr><th>#</th><th>Actie</th><th>Proto</th><th>Bron</th><th>Bestemming</th><th>Poort</th><th>Beschrijving</th></tr><tr class='block'><td>1</td><td>Block</td><td>TCP</td><td>CLIENT subnets</td><td>192.168.10.10</td><td>445</td><td>onderhoud</td></tr><tr class='pass'><td>2</td><td>Pass</td><td>Any</td><td>CLIENT subnets</td><td>any</td><td>*</td><td>TEMP</td></tr></table>","q":"Een client opent \\\\SRV01\\Gedeeld (TCP 445 op 192.168.10.10). Wat gebeurt er?","o":["Geblokkeerd door regel 1","Toegelaten door regel 2","Toegelaten: Pass wint altijd van Block","Geblokkeerd door de Default deny"],"a":0,"w":[null,"Regel 2 wordt nooit bereikt: regel 1 past al.","pfSense kijkt naar de volgorde, niet naar het type regel.","Er past al een regel vóór de Default deny."],"e":"Eerste passende regel beslist. Zet je regel 2 boven regel 1, dan wordt het toegelaten."},{"s":"<b>Situatie</b><br>Regels op <b>CLIENT</b>:<table class='rules'><tr><th>#</th><th>Actie</th><th>Proto</th><th>Bron</th><th>Bestemming</th><th>Poort</th><th>Beschrijving</th></tr><tr class='block'><td>1</td><td>Block</td><td>TCP</td><td>CLIENT subnets</td><td>192.168.10.10</td><td>445</td><td>onderhoud</td></tr><tr class='pass'><td>2</td><td>Pass</td><td>Any</td><td>CLIENT subnets</td><td>any</td><td>*</td><td>TEMP</td></tr></table>","q":"Een client voert <code>nslookup srv01.cursus.local 192.168.10.10</code> uit (UDP 53). Wat gebeurt er?","o":["Toegelaten door regel 2","Geblokkeerd door regel 1","Geblokkeerd door de Default deny","Toegelaten door de anti-lockoutregel"],"a":0,"w":[null,"Regel 1 past alleen op TCP-poort 445.","Regel 2 past.","De anti-lockoutregel staat alleen op LAN/SERVER en geldt voor de webinterface."],"e":"Regel 1 past niet (ander protocol en poort), dus pfSense kijkt naar regel 2: Pass."},{"s":"<b>Situatie</b><br>Je maakt op CLIENT een Pass-regel en klikt op <b>Save</b>. Bovenaan staat ‘The firewall rule configuration has been changed. You must apply the changes in order for them to take effect.’","q":"Is de regel al actief?","o":["Nee, pas na Apply Changes","Ja, Save activeert meteen","Ja, na 60 seconden","Alleen voor nieuwe verbindingen"],"a":0,"w":[null,"Save bewaart alleen in de configuratie.","Er is geen wachttijd; je moet toepassen.","Hij is voor geen enkele verbinding actief tot je toepast."],"e":"Save + Apply Changes. Vergeten toepassen is een klassieke foutbron."},{"s":"<b>Situatie</b><br>Regels op <b>CLIENT</b>:<table class='rules'><tr><th>#</th><th>Actie</th><th>Proto</th><th>Bron</th><th>Bestemming</th><th>Poort</th><th>Beschrijving</th></tr><tr class='pass'><td>1</td><td>Pass</td><td>TCP/UDP</td><td>CLIENT subnets</td><td>192.168.10.10</td><td>53</td><td>DNS</td></tr><tr class='pass'><td>2</td><td>Pass</td><td>TCP</td><td>CLIENT subnets</td><td>192.168.10.10</td><td>445</td><td>SMB</td></tr></table>Geen andere regels.","q":"Een client pingt 192.168.10.10. Wat gebeurt er?","o":["Geblokkeerd: ICMP past in geen enkele regel","Toegelaten: de server is een toegelaten bestemming","Toegelaten door regel 1","Geblokkeerd door regel 2"],"a":0,"w":[null,"Ook het protocol moet passen.","Regel 1 geldt voor TCP/UDP poort 53, niet voor ICMP.","Regel 2 is een Pass-regel; ze past gewoon niet."],"e":"Gerichte regels laten alleen toe wat erin staat. Wil je ping als diagnose, voeg dan een ICMP-regel toe."},{"s":"<b>Situatie</b><br>Op CLIENT staat een regel <i>Pass · Any · bron <b>192.168.20.100</b> · bestemming any</i>. De client stond eerst statisch op 192.168.20.100 en krijgt nu via DHCP 192.168.20.101.","q":"Wat merkt de client?","o":["Niets werkt meer over de grens: het nieuwe adres past niet","Alles werkt nog: de regel volgt automatisch de client","Alleen DNS werkt nog, want daarvoor is geen regel nodig","De client krijgt geen lease meer via de relay"],"a":0,"w":[null,"Een bron met één adres volgt niemand.","Er is geen aparte DNS-regel.","De relay werkt los van deze regel."],"e":"Gebruik ‘CLIENT subnets’ (cursus: ‘CLIENT net’) als bron, dan blijft de regel kloppen voor elk adres in 192.168.20.0/24."},{"s":"<b>Situatie</b><br>Op <b>SERVER</b> staan alleen de standaardregels (anti-lockout en ‘Default allow LAN to any’). Op <b>CLIENT</b> staat alleen ‘Pass · TCP · CLIENT subnets → 192.168.10.10 poort 445’.","q":"De Windows Server start zelf een verbinding naar 192.168.20.100 poort 3389. Wordt ze door pfSense toegelaten?","o":["Ja: ze komt binnen via SERVER en past op ‘allow LAN to any’","Nee: op CLIENT staat geen regel voor poort 3389","Nee: servers mogen nooit verbindingen naar clients starten","Ja, omdat poort 445 open staat"],"a":0,"w":[null,"De regels op CLIENT gelden voor verkeer dat via CLIENT binnenkomt; deze verbinding komt binnen op SERVER.","pfSense kent zo'n vaste regel niet; het hangt van de regels af.","Poort 445 heeft hier niets mee te maken."],"e":"De richting bepaalt de interface. Wil je dit verhinderen, dan beperk je de standaardregel op SERVER."}],
"uitvoer":[{"out":"C:\\> ping 192.168.20.1\n\nPinging 192.168.20.1 with 32 bytes of data:\nRequest timed out.\nRequest timed out.\n\nC:\\> arp -a\n\nInterface: 192.168.20.100 --- 0x5\n  Internet Address      Physical Address      Type\n  192.168.20.1          00-0c-29-4b-7e-12     dynamic","s":"<b>Situatie</b><br>CLIENT01 heeft statisch 192.168.20.100/24, gateway 192.168.20.1.","q":"Wat kan je hieruit besluiten?","o":["ARP werkt, dus de lokale verbinding klopt; ICMP wordt geblokkeerd","De client hangt aan het verkeerde virtuele netwerk (VMnet2)","pfSense staat uit of is nog aan het opstarten","Het subnetmasker van de client is fout ingesteld"],"a":0,"w":[null,"Dan zou ARP geen MAC-adres van 192.168.20.1 vinden.","Een uitgeschakelde pfSense beantwoordt ook geen ARP.","Met een fout masker zie je meestal geen ARP-regel voor de gateway."],"e":"ARP antwoordt alleen als het toestel echt op hetzelfde netwerk zit. De ping valt daarna weg: kijk in het firewalllog."},{"out":"C:\\> ping 192.168.10.10\n\nReply from 192.168.10.10: bytes=32 time<1ms TTL=127\nReply from 192.168.10.10: bytes=32 time<1ms TTL=127","s":"<b>Situatie</b><br>Een Windows-client in 192.168.20.0/24 pingt de Windows Server. Windows start met een TTL van 128.","q":"Wat vertelt TTL=127?","o":["Het pakket passeerde één router","De verbinding is versleuteld","Er zijn 127 ms vertraging","De server gebruikt Linux"],"a":0,"w":[null,"TTL heeft niets met versleuteling te maken.","De tijd staat in time=; TTL is een teller.","Windows begint op 128; Linux op 64."],"e":"Elke router verlaagt de TTL met 1. 128 − 1 = 127: precies één router (pfSense) onderweg."},{"out":"Ethernet adapter Ethernet0:\n   DHCP Enabled. . . . . . . . . . . : Yes\n   Autoconfiguration IPv4 Address. . : 169.254.83.17(Preferred)\n   Subnet Mask . . . . . . . . . . . : 255.255.0.0\n   Default Gateway . . . . . . . . . :\n   DNS Servers . . . . . . . . . . . : fec0:0:0:ffff::1%1","s":"<b>Situatie</b><br>Een client in het CLIENT-netwerk staat op automatisch en vroeg net een lease aan.","q":"Wat zegt deze uitvoer?","o":["Geen DHCP-antwoord ontvangen: scope, relay of netwerkpad","De DHCP-server gaf bewust een adres uit 169.254.0.0/16","De client heeft een statisch adres dat toevallig zo begint","De firewall blokkeert ping naar de DHCP-server"],"a":0,"w":[null,"Een DHCP-server deelt geen 169.254-adressen uit; Windows geeft die zichzelf.","DHCP Enabled: Yes.","Over ping zegt deze uitvoer niets."],"e":"APIPA is een symptoom: ‘geen lease’. Onderzoek daarna scope, relay (downstream/upstream) en de pfSense-DHCP-server."},{"out":"   IPv4 Address. . . . . . . . . . . : 192.168.20.100(Preferred)\n   Subnet Mask . . . . . . . . . . . : 255.255.255.0\n   Default Gateway . . . . . . . . . : 192.168.20.1\n   DHCP Server . . . . . . . . . . . : 192.168.10.10\n   DNS Servers . . . . . . . . . . . : 192.168.10.10\n   Connection-specific DNS Suffix  . : cursus.local","s":"<b>Situatie</b><br>Een client in het CLIENT-netwerk kreeg net een lease.","q":"Welke uitspraak klopt?","o":["De lease komt van de Windows-server; pfSense deed de relay","pfSense is hier de DHCP-server die de lease rechtstreeks uitgaf","De client zit in het SERVER-netwerk 192.168.10.0/24","De DNS-server is fout: 192.168.10.10 hoort er niet"],"a":0,"w":[null,"Dan zou DHCP Server 192.168.20.1 tonen.","Het adres en de gateway zijn uit 192.168.20.0/24.","192.168.10.10 is de DNS-server van het domein: correct."],"e":"DHCP Server 192.168.10.10 + gateway 192.168.20.1 = lease via relay. Alle opties kloppen."},{"out":"PS> Test-NetConnection 192.168.10.10 -Port 445\n\nComputerName     : 192.168.10.10\nRemoteAddress    : 192.168.10.10\nRemotePort       : 445\nInterfaceAlias   : Ethernet0\nSourceAddress    : 192.168.20.100\nTcpTestSucceeded : False","s":"<b>Situatie</b><br>Vanaf dezelfde client lukken <code>ping 192.168.10.10</code> en <code>Test-NetConnection 192.168.10.10 -Port 53</code> (True).","q":"Waar zoek je eerst?","o":["Wat specifiek TCP 445 tegenhoudt: regel op CLIENT, Windows Firewall of SMB","De default gateway van de client en zijn subnetmasker, want het pad over de grens is verdacht","De DNS-server en het DNS-suffix van de client","De DHCP-relay en de scope CLIENT-NETWERK"],"a":0,"w":[null,"Ping en poort 53 over de grens lukken: de gateway werkt.","De test gebruikt een IP-adres, geen naam.","De client heeft al een adres en verkeer over de grens werkt."],"e":"Het pad werkt voor ICMP en poort 53, niet voor 445: zoek wat specifiek poort 445 tegenhoudt."},{"out":"Firewall log (Status › System Logs › Firewall)\nAction  Interface  Rule                       Source               Destination          Protocol\n  ✖     CLIENT     Default deny rule IPv4     192.168.20.100       192.168.10.10        ICMP\n  ✖     CLIENT     Default deny rule IPv4     192.168.20.100:51522 192.168.10.10:53     UDP","s":"<b>Situatie</b><br>Een beheerder bekijkt het log van pfSense.","q":"Wat is de beste volgende stap?","o":["Een Pass-regel op CLIENT maken en de wijziging toepassen","Een Pass-regel op SERVER maken voor dit verkeer","De gateway van de client wijzigen naar 192.168.10.1","De Default deny rule IPv4 verwijderen of uitschakelen"],"a":0,"w":[null,"Het verkeer komt binnen op CLIENT; daar wordt het geblokkeerd.","Het verkeer bereikt pfSense al: de gateway werkt.","De Default deny is verborgen en hoort er te zijn: je maakt toelatingsregels erboven."],"e":"Het log toont waar (CLIENT) en waarom (geen passende regel). Je voegt een Pass-regel toe op CLIENT."},{"out":"PS> Get-DhcpServerv4Scope\n\nScopeId        SubnetMask      Name             State    StartRange      EndRange\n-------        ----------      ----             -----    ----------      --------\n192.168.10.0   255.255.255.0   SERVER-NETWERK   Active   192.168.10.100  192.168.10.200\n192.168.20.0   255.255.255.0   CLIENT-NETWERK   Inactive 192.168.20.100  192.168.20.200","s":"<b>Situatie</b><br>Clients in 192.168.20.0/24 krijgen 169.254-adressen. De relay staat correct (downstream CLIENT, upstream 192.168.10.10).","q":"Wat is de oorzaak?","o":["De scope CLIENT-NETWERK is niet actief","De scope SERVER-NETWERK is fout","Het bereik 100–200 is te klein","Het masker moet 255.255.0.0 zijn"],"a":0,"w":[null,"Die scope is voor het SERVER-subnet en heeft hier niets mee te maken.","Er zijn 101 adressen: ruim genoeg.","/24 klopt met het ontwerp."],"e":"State Inactive: de server biedt geen leases aan uit die scope. <code>Set-DhcpServerv4Scope -ScopeId 192.168.20.0 -State Active</code>."},{"out":"C:\\> nslookup srv01.cursus.local\nServer:  UnKnown\nAddress:  192.168.10.1\n\nDNS request timed out.\n    timeout was 2 seconds.\n*** Request to UnKnown timed-out","s":"<b>Situatie</b><br>Een client in 192.168.20.0/24 kan 192.168.10.10 pingen.","q":"Wat is het probleem?","o":["De client gebruikt 192.168.10.1 als DNS-server, niet 192.168.10.10","De DNS-dienst op de Windows Server is gestopt","De firewall blokkeert ICMP naar de DNS-server","Het A-record srv01 ontbreekt in de zone cursus.local op de Windows Server"],"a":0,"w":[null,"De vraag gaat niet eens naar de server: kijk naar ‘Address’.","Ping lukt; en DNS gebruikt geen ICMP.","Dan zou je ‘Non-existent domain’ krijgen van 192.168.10.10."],"e":"‘Address: 192.168.10.1’ = de gebruikte DNS-server. Controleer optie 006 in de scope en vernieuw de lease."}],
"bewijs":[{"q":"‘Ping naar 192.168.10.10 lukt, dus de gedeelde map werkt.’","o":["Niet overtuigend: ping test ICMP, niet DNS, SMB of rechten","Overtuigend: de server antwoordt, dus de diensten draaien","Overtuigend als de ping onder 1 ms blijft","Niet overtuigend: ping test alleen of DNS werkt"],"a":0,"w":[null,"Antwoorden op ping zegt niets over poort 445 of rechten.","Snelheid verandert niet wat er getest wordt.","Ping op een IP-adres gebruikt geen DNS."],"e":"Test daarna nslookup, poort 445 en de share via de naam."},{"q":"‘De scope CLIENT-NETWERK is actief, dus de clients krijgen een lease.’","o":["Niet overtuigend: de aanvraag moet de server ook bereiken (relay)","Overtuigend: een actieve scope deelt uit","Overtuigend als de opties kloppen","Niet overtuigend: elke scope moet eerst apart in AD geautoriseerd worden"],"a":0,"w":[null,"Een scope bewijst niets over de weg ernaartoe.","Correcte opties helpen pas als er een aanvraag binnenkomt.","Autoriseren gebeurt per server, niet per scope."],"e":"Bewijs: ipconfig /all met DHCP Server 192.168.10.10 en een adres uit 192.168.20.100–200."},{"q":"‘De client heeft 192.168.20.105 uit de juiste pool, dus de configuratie is in orde.’","o":["Niet overtuigend: ook masker, gateway, DNS en suffix tellen","Overtuigend: het adres komt uit de juiste pool","Overtuigend als ‘DHCP Enabled’ op Yes staat en de lease nog geldig is","Niet overtuigend: het adres moet precies .100 zijn"],"a":0,"w":[null,"Een lease kan een goed adres en foute opties hebben.","Dat zegt alleen dat de client DHCP gebruikt.","Elk vrij adres uit de pool is goed."],"e":"Controleer het volledige ipconfig /all, inclusief DHCP Server."},{"q":"‘Na de any-any-regel werkt alles, dus het netwerk is veilig.’","o":["Niet overtuigend: het werkt, maar is niet beperkt","Overtuigend: alle verkeer passeert nu pfSense","Overtuigend als de regel ook gelogd wordt","Niet overtuigend: any-any werkt alleen voor ping"],"a":0,"w":[null,"Het passeert pfSense, maar alles wordt toegelaten.","Loggen maakt het zichtbaar, niet beperkt.","Any omvat alle protocollen."],"e":"Functioneel ≠ beveiligd. Vervang door gerichte regels en test opnieuw."},{"q":"‘arp -a toont 192.168.20.1 met een MAC-adres, dus de client zit op het juiste virtuele netwerk.’","o":["Overtuigend: alleen een buur op hetzelfde netwerk antwoordt","Niet overtuigend: ARP-vragen gaan ook door routers","Niet overtuigend: ARP-regels zijn altijd statisch ingesteld","Niet overtuigend: ARP bewijst alleen dat DNS werkt"],"a":0,"w":[null,"ARP blijft binnen het broadcastdomein.","‘dynamic’ betekent net dat er een antwoord kwam.","ARP heeft niets met namen te maken."],"e":"Een ARP-antwoord van 192.168.20.1 bewijst de lokale verbinding met pfSense, ook als ping geblokkeerd wordt."},{"q":"‘Test-NetConnection 192.168.10.10 -Port 445 geeft True, dus student01 mag de share openen.’","o":["Niet overtuigend: poort open, maar rechten zijn een andere laag","Overtuigend: als SMB bereikbaar is, werkt de share","Overtuigend als ook ping naar de server lukt, dan is het pad volledig bewezen","Niet overtuigend: 445 is de poort van DNS"],"a":0,"w":[null,"SMB is bereikbaar; rechten worden pas daarna gecontroleerd.","Ping voegt niets toe over rechten.","DNS is 53; SMB is 445."],"e":"Open \\\\SRV01\\Gedeeld als student01 zelf."}],
"exit1":[{"s":"<b>Situatie</b><br>Een Windows Server en een Windows-client staan in hetzelfde subnet op dezelfde virtuele switch.","q":"Welk toestel kan verkeer van de client naar de server tegenhouden vóór het de server bereikt?","o":["Geen enkel netwerktoestel: het gaat rechtstreeks","De default gateway, die al het verkeer ziet","De DNS-server, die elke verbinding opzoekt","De DHCP-server, die adressen kan intrekken"],"a":0,"w":[null,"Lokaal verkeer gebruikt de gateway niet.","DNS vertaalt namen, het filtert geen verkeer.","DHCP deelt alleen configuratie uit."],"e":"Alleen de Windows Firewall op de server zelf kan nog iets doen. Daarom plaatsen we pfSense ertussen."},{"s":"<b>Situatie</b><br>Client 192.168.20.115/24, gateway 192.168.20.1.","q":"Naar welk MAC-adres stuurt de client een pakket voor 192.168.10.10?","o":["Het MAC-adres van 192.168.20.1 (pfSense CLIENT)","Het MAC-adres van 192.168.10.10","Het MAC-adres van 192.168.10.1","Het broadcastadres ff-ff-ff-ff-ff-ff, zodat pfSense het oppikt"],"a":0,"w":[null,"De server zit niet in zijn netwerk: zijn MAC-adres kan hij niet opvragen.","Dat adres ligt ook buiten zijn subnet.","Gewoon IP-verkeer gaat gericht naar de gateway."],"e":"IP-bestemming blijft 192.168.10.10; het frame gaat naar het MAC-adres van de gateway."},{"s":"<b>Situatie</b><br>Na de installatie heeft pfSense drie netwerkkaarten: em0, em1, em2. In VMware: adapter 1 = VMnet8, adapter 2 = VMnet2 (SERVER), adapter 3 = VMnet3 (CLIENT).","q":"Wat gebruik je om em-kaarten betrouwbaar aan WAN, SERVER en CLIENT te koppelen?","o":["De MAC-adressen in VMware en in de console","De volgorde van de kaarten","De snelheid van elke kaart","De IP-adressen die pfSense na de installatie al kreeg"],"a":0,"w":[null,"Die volgorde is niet gegarandeerd gelijk.","Alle virtuele kaarten hebben dezelfde snelheid.","Alleen WAN heeft na de installatie een adres."],"e":"Noteer de MAC-adressen vóór je toewijst."},{"s":"<b>Situatie</b><br>In de console geef je de interface naar het servernetwerk 192.168.10.1/24.","q":"Welke upstream gateway vul je in?","o":["Geen","192.168.10.10","192.168.10.254","192.168.20.1"],"a":0,"w":[null,"De server is geen router.","Er bestaat geen router op dat adres.","Dat is pfSense zelf."],"e":"Upstream gateway alleen op WAN; interne netwerken zijn rechtstreeks aangesloten."},{"s":"<b>Situatie</b><br>pfSense heeft net zijn interfaces gekregen: SERVER (vroeger LAN) en CLIENT (vroeger OPT1). Er zijn nog geen eigen regels.","q":"Waarom kan een client in CLIENT nog niets bereiken, terwijl de server in SERVER pfSense wel kan pingen?","o":["SERVER krijgt standaard toelatingsregels, CLIENT geen enkele","CLIENT heeft nog geen IP-adres gekregen in de console","De client heeft nog geen DNS-server om pfSense te vinden","pfSense routeert standaard alleen van SERVER naar CLIENT"],"a":0,"w":[null,"CLIENT heeft 192.168.20.1/24 gekregen.","Ping op een IP-adres gebruikt geen DNS.","Routering werkt in beide richtingen; de firewall beslist."],"e":"Extra interfaces beginnen zonder regels: alles wat binnenkomt, valt op de Default deny."}],
"exit2":[{"s":"<b>Situatie</b><br>Je wilt verkeer van clients (192.168.20.0/24) naar de server (192.168.10.10) toelaten.","q":"Op welke interface plaats je de regel?","o":["CLIENT","SERVER","WAN","Op CLIENT én SERVER"],"a":0,"w":[null,"Daar komt het clientverkeer niet binnen.","WAN is voor verkeer van buitenaf.","Het antwoord mag automatisch terug (stateful)."],"e":"Op de interface waar het verkeer binnenkomt."},{"s":"<b>Situatie</b><br>Een client in CLIENT kan 192.168.10.10 pingen. <code>nslookup srv01.cursus.local</code> faalt. ipconfig toont DNS Servers 192.168.10.10. Test-NetConnection 192.168.10.10 -Port 53 geeft False.","q":"Wat onderzoek je eerst?","o":["Laat CLIENT poort 53 toe, en draait de DNS-dienst?","Klopt de default gateway van de client nog?","Stuurt de DHCP-relay de aanvragen correct door?","Kloppen de share- en NTFS-machtigingen op de server?"],"a":0,"w":[null,"Ping over de grens lukt al.","De client heeft al een correcte configuratie.","We zitten nog niet op toepassingsniveau."],"e":"IP werkt, poort 53 niet: firewallregel of DNS-dienst."},{"s":"<b>Situatie</b><br>Een client stuurt een DHCP Discover. pfSense draait een relay met downstream CLIENT en upstream 192.168.10.10.","q":"Waarom is de relay nodig?","o":["Een broadcast gaat niet door een router naar een ander subnet","De Windows DHCP-server kan geen UDP-verkeer ontvangen","pfSense moet zelf het adres voor de client kiezen","Zonder relay krijgt de client geen default gateway en kan hij niet routeren"],"a":0,"w":[null,"Hij ontvangt wel UDP; de broadcast komt er alleen niet.","De Windows-server kiest het adres.","De gateway is een scopeoptie, los van de relay."],"e":"De relay maakt van de broadcast een gericht bericht naar de server."},{"s":"<b>Situatie</b><br>Een client krijgt 192.168.20.115/24, maar optie 003 (router) in de scope staat op 192.168.10.1.","q":"Wat gebeurt er?","o":["De gateway ligt buiten zijn subnet: alles daarbuiten faalt","Alles werkt: 192.168.10.1 is ook een adres van pfSense","Alleen DNS werkt niet, de rest gaat via pfSense","De client krijgt een APIPA-adres in plaats van een lease"],"a":0,"w":[null,"Het adres moet in het eigen subnet liggen; de client kan het via ARP niet vinden.","Alles buiten het subnet faalt, ook DNS naar 192.168.10.10.","De lease zelf komt wel."],"e":"Optie 003 moet 192.168.20.1 zijn: de pfSense-interface in het eigen subnet."},{"s":"<b>Situatie</b><br>De relay staat aan en upstream is 192.168.10.10. Toch krijgt de client geen lease. De scope CLIENT-NETWERK is actief.","q":"Welke instelling controleer je eerst op pfSense?","o":["Is CLIENT als downstream-interface geselecteerd?","Heeft de WAN-interface een upstream gateway?","Draait de webinterface op HTTPS in plaats van HTTP?","Staat de anti-lockoutregel nog op de SERVER-interface?"],"a":0,"w":[null,"WAN speelt geen rol in de relay.","Dat heeft niets met DHCP te maken.","Die regel beschermt alleen de toegang tot de webinterface."],"e":"De relay moet luisteren waar de aanvragen ontstaan. Daarna: pfSense-DHCP-server uit? Servergateway?"}]
};
